import { createWorkspace } from "@tigrisdata/agent-kit";
import fs from "node:fs";
import path from "node:path";

async function main() {
  const now = new Date();

  console.log("Creating Tigris workspace 'long-running-eval-ws' with 7-day TTL...");

  const { workspace, error } = await createWorkspace("long-running-eval-ws", {
    ttl: { days: 7 },
    credentials: { role: "ReadOnly" },
  });

  if (error) {
    console.error("Error creating workspace:", error);
    process.exit(1);
  }

  if (!workspace) {
    console.error("Workspace creation returned no workspace and no error.");
    process.exit(1);
  }

  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const output = {
    bucket: workspace.bucket,
    expires_at: expiresAt.toISOString(),
  };

  const outputPath = path.join(process.cwd(), "workspace.json");
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log(`Workspace created successfully.`);
  console.log(`Bucket: ${output.bucket}`);
  console.log(`Expires at: ${output.expires_at}`);
  console.log(`Output written to ${outputPath}`);
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

