import { createWorkspace } from "@tigrisdata/agent-kit";
import fs from "node:fs";
import path from "node:path";

async function main() {
  const now = new Date();
  const workspaceName = "long-running-eval-ws";

  console.log(`Creating Tigris workspace '${workspaceName}' with 7-day TTL...`);

  const response = await createWorkspace(workspaceName, {
    ttl: { days: 7 },
    credentials: { role: "ReadOnly" },
  });

  if (response.error) {
    console.error("Error creating workspace:", response.error);
    process.exit(1);
  }

  const workspace = response.data;
  if (!workspace) {
    console.error("Workspace creation returned no data and no error.");
    process.exit(1);
  }

  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const output = {
    bucket: workspace.bucket,
    expires_at: expiresAt.toISOString(),
  };

  const outputPath = path.join(process.cwd(), "workspace.json");
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log(`Workspace created successfully.`);
  console.log(`Bucket: ${output.bucket}`);
  console.log(`Expires at: ${output.expires_at}`);
  console.log(`Output written to ${outputPath}`);
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});
